290	// isOutdated compares current and latest versions using semantic versioning.
291	// Returns true if current < latest.
292	func isOutdated(current, latest string) bool {
293		// Ensure versions have "v" prefix for semver package
294		if !strings.HasPrefix(current, "v") {
295			current = "v" + current
296		}
297		if !strings.HasPrefix(latest, "v") {
298			latest = "v" + latest
299		}
300	
301		// Skip notification for dev builds (e.g., "1.0.0-dev-xxx").
302		// These are local development builds and shouldn't trigger update notifications.
303		// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
304		if strings.Contains(semver.Prerelease(current), "dev") {
305			return false
306		}
307	
308		// semver.Compare returns -1 if current < latest
309		return semver.Compare(current, latest) < 0
310	}
